// Client-side Privacy & Redaction Engine for AUDIT IT

/**
 * Masks Indian Bank Account Numbers (keeps last 4 digits visible)
 * e.g., "50100239482910" -> "•••• •••• •••• 2910"
 */
export function maskBankAccount(accountNumber) {
  if (!accountNumber) return "";
  const cleaned = accountNumber.toString().replace(/\s+/g, "");
  if (cleaned.length <= 4) return "••••" + cleaned;
  const lastFour = cleaned.slice(-4);
  return "•••• •••• •••• " + lastFour;
}

/**
 * Masks IFSC Codes (keeps bank prefix, masks branch code)
 * e.g., "HDFC0001234" -> "HDFC••••••"
 */
export function maskIFSC(ifsc) {
  if (!ifsc) return "";
  const cleaned = ifsc.trim().toUpperCase();
  if (cleaned.length < 5) return "••••••";
  return cleaned.slice(0, 4) + "••••••";
}

/**
 * Masks phone numbers (keeps last 3 digits)
 * e.g., "+91 9876543210" -> "+91 •••••••210"
 */
export function maskPhone(phone) {
  if (!phone) return "";
  const cleaned = phone.replace(/[^\d+]/g, "");
  if (cleaned.length < 5) return "•••••";
  return cleaned.slice(0, 3) + " •••••••" + cleaned.slice(-3);
}

/**
 * Pre-processes any raw text or object to ensure sensitive financial identifiers
 * are sanitized before UI display or downstream AI requests.
 */
export function sanitizeInvoiceData(rawInvoice) {
  const sanitized = JSON.parse(JSON.stringify(rawInvoice));

  if (sanitized.bank_details) {
    if (sanitized.bank_details.account_number) {
      sanitized.bank_details.account_number = maskBankAccount(sanitized.bank_details.account_number);
    }
    if (sanitized.bank_details.ifsc) {
      sanitized.bank_details.ifsc = maskIFSC(sanitized.bank_details.ifsc);
    }
  }

  return sanitized;
}

// AUDIT IT - Core Audit & Calculation Engine
// RULE: "AI reads, code calculates. Do NOT trust the AI to do math."

/**
 * Standard Indian GSTIN Regex (15 characters)
 * 2 digits (state) + 5 letters (PAN) + 4 digits + 1 letter + 1 char + Z + 1 check digit
 */
export const GSTIN_REGEX = /^[0-9]{2}[A-Z]{5}[0-9]{4}[A-Z]{1}[1-9A-Z]{1}Z[0-9A-Z]{1}$/;

/**
 * Round to 2 decimal places to prevent floating point inaccuracies
 */
export function round2(num) {
  return Math.round((Number(num) + Number.EPSILON) * 100) / 100;
}

/**
 * Formats numbers into Indian Currency format (e.g., ₹1,24,570.00)
 */
export function formatRupees(amount) {
  if (amount === null || amount === undefined || isNaN(amount)) return "₹0.00";
  const num = Number(amount);
  const isNegative = num < 0;
  const absNum = Math.abs(num);

  const parts = absNum.toFixed(2).split(".");
  let intPart = parts[0];
  const decPart = parts[1];

  // Indian currency grouping: last 3 digits, then groups of 2
  if (intPart.length > 3) {
    const lastThree = intPart.substring(intPart.length - 3);
    const otherNumbers = intPart.substring(0, intPart.length - 3);
    intPart = otherNumbers.replace(/\B(?=(\d{2})+(?!\d))/g, ",") + "," + lastThree;
  }

  return (isNegative ? "-₹" : "₹") + intPart + "." + decPart;
}

/**
 * Recalculates and audits an entire invoice.
 * Every mathematical sum is strictly computed in code.
 */
export function auditInvoice(invoice) {
  const issues = [];
  const lineItemAudit = [];

  let sum_items = 0;
  let hasLineItemMathError = false;
  let hasBlurryFields = false;

  // 1. Line Items Verification
  if (!invoice.items || invoice.items.length === 0) {
    issues.push({
      type: "ERROR",
      field: "items",
      title: "No Line Items Detected",
      description: "Invoice contains no billable line items or goods."
    });
  } else {
    invoice.items.forEach((item, index) => {
      const qty = Number(item.qty) || 0;
      const rate = Number(item.rate) || 0;
      const declaredAmount = Number(item.amount) || 0;
      const calculatedAmount = round2(qty * rate);

      sum_items += calculatedAmount;

      const diff = round2(declaredAmount - calculatedAmount);
      const isMathError = Math.abs(diff) > 0.50; // tolerance for rounding

      if (isMathError) {
        hasLineItemMathError = true;
        issues.push({
          type: "ERROR",
          field: `item-${item.id || index}`,
          title: `Line ${index + 1} Calculation Error: ${item.description}`,
          description: `Billed as ${formatRupees(declaredAmount)}, but ${qty} × ${formatRupees(rate)} is ${formatRupees(calculatedAmount)}. Difference of ${formatRupees(Math.abs(diff))}.`,
          diff: diff,
          declared: declaredAmount,
          calculated: calculatedAmount
        });
      }

      if (item.is_blurry) {
        hasBlurryFields = true;
        issues.push({
          type: "WARNING",
          field: `item-blurry-${item.id || index}`,
          title: `Unclear / Blurry Field on Line ${index + 1}`,
          description: item.unclear_note || `The rate or quantity for "${item.description}" could not be confirmed with 100% certainty.`
        });
      }

      lineItemAudit.push({
        ...item,
        qty,
        rate,
        declaredAmount,
        calculatedAmount,
        diff,
        isMathError
      });
    });
  }

  sum_items = round2(sum_items);

  // 2. Tax Calculations
  const cgst = Number(invoice.cgst) || 0;
  const sgst = Number(invoice.sgst) || 0;
  const igst = Number(invoice.igst) || 0;
  const totalTax = round2(cgst + sgst + igst);

  // GST Split check: In intra-state, CGST and SGST must match
  if (cgst > 0 || sgst > 0) {
    if (Math.abs(cgst - sgst) > 1.00) {
      issues.push({
        type: "WARNING",
        field: "gst_split",
        title: "CGST and SGST Mismatch",
        description: `Intra-state GST requires CGST (${formatRupees(cgst)}) to equal SGST (${formatRupees(sgst)}).`
      });
    }
    if (igst > 0) {
      issues.push({
        type: "WARNING",
        field: "gst_type",
        title: "Conflicting GST Types",
        description: "Invoice contains both IGST and CGST/SGST. Typically an invoice is either Intra-state or Inter-state."
      });
    }
  }

  // 3. Strict Grand Total Calculation
  const calculated_total = round2(sum_items + totalTax);
  const total_declared = Number(invoice.total_declared) || 0;
  const totalDiff = round2(total_declared - calculated_total);

  // 4. Discrepancy comparison rule: If they differ by more than ₹1.00
  const hasTotalDiscrepancy = Math.abs(totalDiff) > 1.00;

  if (hasTotalDiscrepancy) {
    issues.push({
      type: "ERROR",
      field: "total_declared",
      title: totalDiff > 0 ? "Grand Total Overcharge Detected" : "Grand Total Undercharge Detected",
      description: `Bill states ${formatRupees(total_declared)}, but verified total (Items ${formatRupees(sum_items)} + Tax ${formatRupees(totalTax)}) is ${formatRupees(calculated_total)}. Difference: ${formatRupees(Math.abs(totalDiff))}.`,
      diff: totalDiff,
      declared: total_declared,
      calculated: calculated_total
    });
  }

  // 5. Header & GSTIN Verification
  const gstin = (invoice.gstin || "").trim().toUpperCase();
  let gstinValid = false;
  if (!gstin) {
    issues.push({
      type: "WARNING",
      field: "gstin",
      title: "Missing Supplier GSTIN",
      description: "No GSTIN found on invoice. Input Tax Credit (ITC) cannot be claimed without a valid supplier GSTIN."
    });
  } else if (!GSTIN_REGEX.test(gstin)) {
    issues.push({
      type: "WARNING",
      field: "gstin",
      title: "Invalid GSTIN Format",
      description: `GSTIN "${gstin}" does not match Indian 15-character GST structure.`
    });
  } else {
    gstinValid = true;
  }

  if (!invoice.invoice_no) {
    issues.push({
      type: "WARNING",
      field: "invoice_no",
      title: "Missing Invoice Number",
      description: "Bill does not state an invoice/cash memo number."
    });
  }

  if (!invoice.date) {
    issues.push({
      type: "WARNING",
      field: "date",
      title: "Missing Invoice Date",
      description: "Bill date is absent or illegible."
    });
  }

  // Determine overall status verdict
  let status = "VERIFIED";
  let statusText = "Math Verified & Valid";
  let statusColor = "emerald";

  if (hasTotalDiscrepancy || hasLineItemMathError) {
    status = "OVERCHARGE_ERROR";
    statusText = totalDiff > 0 ? `${formatRupees(Math.abs(totalDiff))} Overcharge` : `${formatRupees(Math.abs(totalDiff))} Math Error`;
    statusColor = "rose";
  } else if (!gstinValid || hasBlurryFields || issues.some(i => i.type === "WARNING")) {
    status = "REVIEW_NEEDED";
    statusText = "Review Needed";
    statusColor = "amber";
  }

  return {
    status,
    statusText,
    statusColor,
    sum_items,
    totalTax,
    calculated_total,
    total_declared,
    totalDiff,
    hasTotalDiscrepancy,
    hasLineItemMathError,
    hasBlurryFields,
    gstinValid,
    lineItemAudit,
    issues
  };
}

// Generates bilingual (English + Hindi) dispute notes and CA summaries for AUDIT IT
import { formatRupees } from "./auditEngine.js";

/**
 * Generates a ready-to-send dispute note for WhatsApp / SMS to the supplier
 */
export function generateSupplierDisputeNote(invoice, audit) {
  const vendor = invoice.vendor_name || "Supplier";
  const invNo = invoice.invoice_no || "N/A";
  const invDate = invoice.date || "N/A";

  const diffAmount = Math.abs(audit.totalDiff);
  const isOvercharge = audit.totalDiff > 0;

  let note = `*AUDIT DISCREPANCY NOTE / बिल ऑडिट विवरण*\n`;
  note += `------------------------------------\n`;
  note += `To: *${vendor}*\n`;
  note += `Bill / Invoice No: *${invNo}*\n`;
  note += `Date: *${invDate}*\n\n`;

  note += `Namaste ji,\n`;
  note += `We audited the calculations on this invoice and noticed a discrepancy:\n\n`;

  // Itemize line errors
  const lineErrors = audit.issues.filter(i => i.type === "ERROR" && i.field.startsWith("item-"));
  if (lineErrors.length > 0) {
    note += `*Item Calculation Errors:*\n`;
    lineErrors.forEach((err, idx) => {
      note += `${idx + 1}. ${err.title}\n   ↳ ${err.description}\n`;
    });
    note += `\n`;
  }

  note += `*Total Summary:*\n`;
  note += `• Billed Amount on Parcha: *${formatRupees(audit.total_declared)}*\n`;
  note += `• Correct Verified Amount: *${formatRupees(audit.calculated_total)}*\n`;
  note += `• *${isOvercharge ? "Overcharged Amount" : "Difference"}*: *${formatRupees(diffAmount)}*\n\n`;

  if (!audit.gstinValid) {
    note += `⚠️ *GSTIN Notice:* The GSTIN is either missing or unverified. Please share your registered 15-digit GSTIN so we can claim Input Tax Credit (ITC).\n\n`;
  }

  note += `Please review the above numbers and kindly issue a revised bill or a Credit Note (जमा पर्चा) for *${formatRupees(diffAmount)}*.\n\n`;
  note += `Dhanyawad,\nAudit Generated via *AUDIT IT* (Retail Bill Verification)`;

  return note;
}

/**
 * Generates an accounting ledger summary string for CA / tax consultant
 */
export function generateCaSummaryText(invoice, audit) {
  return `AUDIT IT - FORMAL INVOICE AUDIT SLIP
=========================================
Vendor Name: ${invoice.vendor_name || "N/A"}
Supplier GSTIN: ${invoice.gstin || "MISSING / UNVERIFIED"}
Invoice Number: ${invoice.invoice_no || "N/A"}
Invoice Date: ${invoice.date || "N/A"}
-----------------------------------------
Audit Status: ${audit.statusText.toUpperCase()}
Sum of Line Items: ${formatRupees(audit.sum_items)}
Total Declared GST: ${formatRupees(audit.totalTax)} (CGST: ${formatRupees(invoice.cgst || 0)}, SGST: ${formatRupees(invoice.sgst || 0)}, IGST: ${formatRupees(invoice.igst || 0)})
Verified Grand Total: ${formatRupees(audit.calculated_total)}
Billed Grand Total: ${formatRupees(audit.total_declared)}
Variance / Difference: ${formatRupees(audit.totalDiff)}
-----------------------------------------
Issues Logged (${audit.issues.length}):
${audit.issues.map((i, idx) => `[${idx + 1}] [${i.type}] ${i.title}: ${i.description}`).join("\n")}
=========================================
Audited by AUDIT IT Engine - 100% Calculated via Deterministic Code`;
}
